mapper.select:
SELECT k.id, k.name, k.desc, k.type, k.user_id, u.nickname, k.create_time, COALESCE(doc_stats.document_count, 0) AS document_count, COALESCE(doc_stats.char_length, 0) AS char_length, COALESCE(res_stats.resource_count, 0) AS resource_count FROM knowledge k LEFT JOIN "user" u ON k.user_id = u.id
LEFT JOIN ( SELECT m.target_id, COUNT(*) AS resource_count FROM resource_mapping m WHERE m.target_type = 'KNOWLEDGE' GROUP BY m.target_id ) res_stats ON k.id = res_stats.target_id
AND k.user_id = #{query.createUser}
AND k.name LIKE CONCAT('%', #{query.name}, '%')
AND k.folder_id = #{query.folderId}
AND k.type = #{query.type}
ORDER BY k.create_time DESC
